DROP TABLE IF EXISTS `basket_tournament`;
CREATE TABLE `basket_tournament` (
  `id` bigint NOT NULL AUTO_INCREMENT COMMENT '主键',
  `tournament_no` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '赛事编号',
  `competition_season_id` bigint DEFAULT NULL COMMENT '所属顶层赛季主键',
  `tournament_name` varchar(128) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '赛事名称',
  `short_name` varchar(64) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '赛事简称',
  `english_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '英文名称',
  `logo_file_id` bigint DEFAULT NULL COMMENT '赛事标志文件主键',
  `cover_file_id` bigint DEFAULT NULL COMMENT '赛事封面文件主键',
  `tournament_type` varchar(32) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '赛事类型',
  `game_terminal` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL COMMENT '比赛终端',
  `format_code` varchar(16) COLLATE utf8mb4_unicode_ci NOT NULL DEFAULT '5V5' COMMENT '比赛赛制',
  `organizer_name` varchar(128) COLLATE utf8mb4_unicode_ci DEFAULT NULL COMMENT '主办方名称',
  `description` longtext COLLATE utf8mb4_unicode_ci COMMENT '赛事介绍',
  `registration_start_time` datetime DEFAULT NULL COMMENT '报名开始时间',
  `registration_end_time` datetime DEFAULT NULL COMMENT '报名结束时间',
  `competition_start_time` datetime DEFAULT NULL COMMENT '比赛开始时间',
  `competition_end_time` datetime DEFAULT NULL COMMENT '比赛结束时间',
  `tournament_status` tinyint NOT NULL DEFAULT '1' COMMENT '赛事状态',
  `public_status` tinyint NOT NULL DEFAULT '1' COMMENT '公开状态',
  `display_order` int NOT NULL DEFAULT '0' COMMENT '展示顺序',
  `create_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP COMMENT '创建时间',
  `update_time` datetime NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP COMMENT '更新时间',
  `is_delete` tinyint NOT NULL DEFAULT '0' COMMENT '删除标记',
  PRIMARY KEY (`id`),
  UNIQUE KEY `uk_tournament_no` (`tournament_no`),
  UNIQUE KEY `uk_tournament_name_delete` (`tournament_name`,`is_delete`),
  KEY `idx_tournament_terminal_status` (`game_terminal`,`tournament_status`,`public_status`),
  KEY `idx_tournament_display` (`public_status`,`display_order`),
  KEY `idx_tournament_competition_season` (`competition_season_id`,`tournament_status`)
) ENGINE=InnoDB AUTO_INCREMENT=6 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci COMMENT='赛事主表';
