  UNIQUE KEY `uk_admin_tournament_scope` (`admin_user_id`,`tournament_id`,`scope_code`,`active_flag`,`is_delete`),
  KEY `idx_tournament_scope_tournament` (`tournament_id`,`active_flag`)
